  if(!validId || !['state','input'].includes(route))return json({error:'Room not found.'},404);
  if(route==='state' && (req.method!=='GET' || path.length!==3)) return json({error:'Invalid state request.'},400);
  if(route==='input' && !['POST','GET'].includes(req.method))return json({error:'Use GET or POST.'},405);
  const key='rooms/'+id;
